def to_int(text, default=0):
    try:
        return int(str(text).strip())
    except (ValueError, TypeError):
        return default

print(to_int(" 42 "))   # 42
print(to_int("five"))   # 0

def parse_item(line: str) -> tuple[str, int, float]:
    parts = [p.strip() for p in line.split(",")]
    if len(parts) != 3:
        raise ValueError(f"expected 3 fields, got {len(parts)}: {line!r}")
    name, qty_text, price_text = parts
    return name, int(qty_text), float(price_text)

print(parse_item("dosa, 2, 60.5"))

