async function getMarks(id: number): Promise<number> {
  const r = await fetch("/api/marks/" + id);
  if (!r.ok) throw new Error("HTTP " + r.status);
  const data: { marks: number } = await r.json();
  return data.marks;
}

async function safe(id: number): Promise<number> {
  try {
    return await getMarks(id);
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : "unknown";
    console.log("failed: " + msg);
    return 0;
  }
}

async function total(a: number, b: number): Promise<number> {
  const pair: [number, number] = await Promise.all([getMarks(a), getMarks(b)]);
  return pair[0] + pair[1];
}

