async function retry<T>(fn: () => Promise<T>, n = 3): Promise<T> {
  try { return await fn(); }
  catch (e) { if (n <= 1) throw e; return retry(fn, n - 1); }
}

type Result<T> = { ok: true; value: T } | { ok: false; error: string };
