func fanIn(a, b <-chan string) <-chan string {
  out := make(chan string)
  go func() {
    for a != nil || b != nil {
      select {
      case m, ok := <-a:
        if !ok { a = nil; continue }
        out <- m
      case m, ok := <-b:
        if !ok { b = nil; continue }
        out <- m
      }
    }
    close(out)
  }()
  return out
}

