package main

import (
	"context"
	"errors"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"
)

func main() {
	srv := &http.Server{Addr: ":8080"
	go func() {
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			slog.Error("listen failed", "err", err)
		}
	}()
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := srv.Shutdown(ctx); err != nil {
		slog.Error("shutdown failed", "err", err)
	}
}

package main

import "fmt"

type Pricer interface {
	Price(dish string) (float64, bool)
}

type Service struct{ p Pricer }

func (s Service) Bill(dish string, qty int) (float64, error) {
	unit, ok := s.p.Price(dish)
	if !ok {
		return 0, fmt.Errorf("unknown dish: %s", dish)
	}
	return unit * float64(qty), nil
}

type Menu map[string]float64

func (m Menu) Price(dish string) (float64, bool) {
	v, ok := m[dish]
	return v, ok
}

func main() {
	s := Service{p: Menu{"dosa": 60}}
	fmt.Println(s.Bill("dosa", 2))
}

